// Sound structural implications on immutable expressions. If both XOR inputs
// vanish outside C, so does their XOR. Positive AND retains every input factor.
fn guard_facts(e:&Expr,v:E,depth:usize,cache:&mut HashMap<E,BTreeSet<E>>)->BTreeSet<E>{if v<=1{return BTreeSet::new();}if let Some(x)=cache.get(&v){return x.clone();}let mut out=BTreeSet::from([v]);if depth>0{let(k,a,b)=e.nodes[(v/2-1)as usize];if k==1&&v&1==0{out.extend(guard_facts(e,a,depth-1,cache));out.extend(guard_facts(e,b,depth-1,cache));}else if k==2{let pairs=if v&1==0{[(a,b),(a^1,b^1)]}else{[(a^1,b),(a,b^1)]};for(a,b)in pairs{let a=guard_facts(e,a,depth-1,cache);let b=guard_facts(e,b,depth-1,cache);out.extend(a.intersection(&b).copied());}}}let out:BTreeSet<_>=out.into_iter().take(32).collect();if cache.len()<500000{cache.insert(v,out.clone());}out}
fn implicit_guards(ops:&[Op])->(Vec<Op>,serde_json::Value){let no=u64::MAX;let(nq,nb,_,_)=quantum_ecc::circuit::analyze_ops(ops.iter());let mut alg=Algebra{inner:Expr::default()};let(mut q,mut c)=initial_inputs(ops,nq as usize,nb as usize,&mut alg);let mut index=HashMap::<E,BTreeSet<usize>>::new();for(bit,&v)in c.iter().enumerate(){if v>1{index.entry(v).or_default().insert(bit);}}let(mut base,mut stack)=(1,vec![]);let mut facts=HashMap::new();let mut out=Vec::with_capacity(ops.len());let mut rows=vec![];
 for(i,o)in ops.iter().enumerate(){if o.kind==K::PushCondition{out.push(*o);stack.push(base);base=alg.inner.and(base,c[o.c_condition.0 as usize]);continue;}if o.kind==K::PopCondition{out.push(*o);base=stack.pop().unwrap();continue;}let g=if o.c_condition.0==no{base}else{alg.inner.and(base,c[o.c_condition.0 as usize])};let(t,a,b,ct)=(o.q_target.0 as usize,o.q_control1.0 as usize,o.q_control2.0 as usize,o.c_target.0 as usize);let mut clauses=vec![];
  if o.kind==K::CCX{let ab=alg.inner.and(q[a],q[b]);let f=alg.inner.and(g,ab);if f>1{let ff=guard_facts(&alg.inner,f,8,&mut facts);let mut narrowed=g;for wanted in ff{if wanted<=1{continue;}let candidate=if let Some(bits)=index.get(&wanted){bits.first().copied().map(|bit|(bit,false))}else{index.get(&(wanted^1)).and_then(|bits|bits.first().copied()).map(|bit|(bit,true))};if let Some((bit,neg))=candidate{if alg.inner.quick_implies(narrowed,wanted,16)||alg.inner.and(narrowed,wanted^1)==0||clauses.contains(&(bit,neg)){continue;}clauses.push((bit,neg));narrowed=alg.inner.and(narrowed,wanted);if clauses.len()==4{break;}}}}}
  if clauses.is_empty(){out.push(*o);}else{for &(bit,neg)in &clauses{let cond=if neg{out.push(make(K::BitStore1,no,no,no,nb,no));out.push(make(K::BitInvert,no,no,no,nb,bit as u64));nb}else{bit as u64};out.push(make(K::PushCondition,no,no,no,no,cond));}out.push(*o);for _ in &clauses{out.push(make(K::PopCondition,no,no,no,no,no));}rows.push(serde_json::json!({"record":i,"clauses":clauses}));}
  let changed=matches!(o.kind,K::Hmr|K::BitInvert|K::BitStore0|K::BitStore1);if changed&&c[ct]>1{let old=c[ct];let bits=index.get_mut(&old).unwrap();assert!(bits.remove(&ct));if bits.is_empty(){index.remove(&old);}}
  match o.kind{K::X=>q[t]=alg.inner.xor(q[t],g),K::CX=>{let v=alg.inner.and(q[a],g);q[t]=alg.inner.xor(q[t],v);},K::CCX=>{let v=alg.inner.and(q[a],q[b]);let v=alg.inner.and(v,g);q[t]=alg.inner.xor(q[t],v);},K::Swap=>{let v=alg.inner.xor(q[a],q[t]);let v=alg.inner.and(g,v);q[a]=alg.inner.xor(q[a],v);q[t]=alg.inner.xor(q[t],v);},K::R|K::Hmr=>{q[t]=alg.inner.and(q[t],g^1);if o.kind==K::Hmr{let r=alg.inner.atom();c[ct]=alg.inner.ite(g,r,c[ct]);}},K::BitInvert=>c[ct]=alg.inner.xor(c[ct],g),K::BitStore0=>c[ct]=alg.inner.and(c[ct],g^1),K::BitStore1=>c[ct]=alg.inner.or(c[ct],g),K::Neg|K::Z|K::CZ|K::CCZ|K::Register|K::AppendToRegister|K::DebugPrint=>{},_=>unreachable!()}
  if changed&&c[ct]>1{index.entry(c[ct]).or_default().insert(ct);}if i%1000000==0{eprintln!("IMPLICIT_GUARD op={i} hits={} fact_cache={} nodes={}",rows.len(),facts.len(),alg.inner.nodes.len());}
 }assert!(stack.is_empty());let output_len=out.len();(out,serde_json::json!({"status":"SOURCE_PROVED_IMPLICIT_CLASSICAL_GUARD_COMPONENT_NOT_SCORED","guarded_ccx":rows.len(),"rows":rows,"input_records_sha3":hash(ops),"input_operations":ops.len(),"output_operations":output_len,"fact_cache_entries":facts.len(),"proof":"Inductive exact AND-factor/XOR-common-factor implication on entire original prefix, matched to CURRENT existing classical bit/complement. Original quantum flip implies every added predicate. Already implied gate guards excluded. At most4extra clauses, same original scope/perop condition, fresh private complement scratch only. No quantum gate or measurement added/removed, CCX executed subset only, quantum width unchanged. No sampling/table/cut/circuit packet tuning. Full protected phase/RNG/state and actual T nonincrease controls required; no score."}))}

#[cfg(test)]mod implicit_guard_tests{use super::*;use quantum_ecc::sim::Simulator;use sha3::digest::XofReader;
 struct W(u64);impl XofReader for W{fn read(&mut self,b:&mut[u8]){b.copy_from_slice(&self.0.to_le_bytes());}}
 fn metadata()->Vec<Op>{let mut ops=vec![];for q in[0,1,3,4]{let mut o=Op::empty();o.kind=K::AppendToRegister;o.q_target=QubitId(q);o.r_target=quantum_ecc::circuit::RegisterId(0);ops.push(o);}for c in 0..2{let mut o=Op::empty();o.kind=K::AppendToRegister;o.c_target=BitId(c);o.r_target=quantum_ecc::circuit::RegisterId(1);ops.push(o);}ops}
 fn compare(ops:&[Op],hits:usize,strict:bool){let(out,r)=implicit_guards(ops);assert_eq!(r["guarded_ccx"],hits);let(nq,nb,_,regs)=quantum_ecc::circuit::analyze_ops(ops.iter());let(nq2,nb2,_,_)=quantum_ecc::circuit::analyze_ops(out.iter());assert_eq!(nq,nq2);for pattern in[0,u64::MAX,0xa55a_dd33_ff00_1188]{let(mut ra,mut rb)=(W(pattern),W(pattern));let(mut a,mut b)=(Simulator::new(nq as usize,nb as usize,&mut ra),Simulator::new(nq2 as usize,nb2 as usize,&mut rb));let mut shift=0;for reg in &regs{for item in reg{for lane in 0..64{let v=(((lane>>(shift%6))&1)as u64)<<lane;match item{quantum_ecc::circuit::QubitOrBit::Qubit(id)=>a.qubits[id.0 as usize]|=v,quantum_ecc::circuit::QubitOrBit::Bit(id)=>a.bits[id.0 as usize]|=v}}shift+=1;}}b.qubits.clone_from(&a.qubits);b.bits[..nb as usize].copy_from_slice(&a.bits);a.apply_iter(ops.iter());b.apply_iter(out.iter());assert_eq!(a.qubits,b.qubits);assert_eq!(a.bits,b.bits[..nb as usize]);assert_eq!(a.phase,b.phase);assert!(a.stats.toffoli_gates>=b.stats.toffoli_gates);if strict{assert!(a.stats.toffoli_gates>b.stats.toffoli_gates);}}}
 #[test]fn masked_quantum_control_yields_strict_positive_classical_guard(){let n=u64::MAX;let mut ops=metadata();ops.extend([make(K::CX,n,0,2,n,0),make(K::CCX,1,2,3,n,n),make(K::R,n,n,2,n,n)]);compare(&ops,1,true);}
 #[test]fn inverted_current_bit_gets_private_complement_without_mutating_original_guards(){let n=u64::MAX;let mut ops=metadata();ops.extend([make(K::CX,n,0,2,n,0),make(K::BitInvert,n,n,n,0,n),make(K::PushCondition,n,n,n,n,1),make(K::CCX,1,2,3,n,n),make(K::PopCondition,n,n,n,n,n)]);compare(&ops,1,true);}
 #[test]fn overwritten_old_guard_is_not_mistaken_for_current_measurement_bit(){let n=u64::MAX;let mut ops=metadata();ops.extend([make(K::CX,n,0,2,n,0),make(K::Hmr,n,n,5,0,n),make(K::CCX,1,2,3,n,n)]);compare(&ops,0,false);}
 #[test]fn xor_terms_share_the_same_mask_and_original_perop_guard(){let n=u64::MAX;let mut ops=metadata();ops.extend([make(K::CX,n,0,2,n,0),make(K::CX,n,1,2,n,0),make(K::CCX,4,2,3,n,1)]);compare(&ops,1,true);}
 #[test]fn already_explicit_guard_is_not_redundantly_inserted(){let n=u64::MAX;let mut ops=metadata();ops.extend([make(K::CX,n,0,2,n,0),make(K::CCX,1,2,3,n,0)]);compare(&ops,0,false);}
 #[test]fn multiple_factors_intersect_and_all_original_bits_remain_equal(){let n=u64::MAX;let mut ops=metadata();ops.extend([make(K::PushCondition,n,n,n,n,0),make(K::CX,n,0,2,n,1),make(K::PopCondition,n,n,n,n,n),make(K::CCX,1,2,3,n,n)]);compare(&ops,1,true);}
 #[test]fn every_structural_factor_is_sound_on_all_six_atom_assignments(){fn value(e:&Expr,v:E,atoms:&[E],row:usize)->bool{if v<=1{return v==1;}let(k,a,b)=e.nodes[(v/2-1)as usize];let raw=match k{0=>row>>atoms.iter().position(|&x|x==v&!1).unwrap()&1!=0,1=>value(e,a,atoms,row)&value(e,b,atoms,row),_=>value(e,a,atoms,row)^value(e,b,atoms,row)};raw^(v&1!=0)}let mut e=Expr::default();let atoms:Vec<_>=(0..6).map(|_|e.atom()).collect();let mut pool=atoms.clone();let mut cache=HashMap::new();let mut seed=17u64;for _ in 0..250{seed=seed.wrapping_mul(6364136223846793005).wrapping_add(1);let a=pool[seed as usize%pool.len()];let b=pool[(seed>>21)as usize%pool.len()];let v=if seed&1==0{e.and(a,b)}else{e.xor(a,b)}^((seed>>37)&1)as E;for f in guard_facts(&e,v,8,&mut cache){for row in 0..64{assert!(!value(&e,v,&atoms,row)||value(&e,f,&atoms,row));}}pool.push(v);if pool.len()>32{pool.remove(6);}}}
}
